cat > /tmp/lua/for1.lua <<'EOF'
for i=1,3 do io.write(i," ") end print()
for i=3,1 do io.write(i,"?") end print("none")
for i=3,1,-1 do io.write(i," ") end print()
for i=1,10,3 do io.write(i," ") end print()
for i=1.0,3 do io.write(i," ",math.type(i)," ") end print()
for i=1,3.5 do io.write(i," ",math.type(i)," ") end print()
for i=0.5,3,0.5 do io.write(i," ") end print()
for i=math.maxinteger-2,math.maxinteger do io.write(i," ") end print()
for i=math.maxinteger-1,math.maxinteger do io.write(i," ") end print()
for i=math.mininteger,math.mininteger+1 do io.write(i," ") end print()
for i=math.maxinteger,math.mininteger,-1 do io.write(i," ") end print("never")
for i=1,3,-1 do io.write(i,"!") end print("never2")
local ok,e = pcall(function() for i=1,10,0 do end end) print(ok,e)
for i=1,3 do local i = i * 10; io.write(i," ") end print()
for i=1,2 do i = i + 100; io.write(i," ") end print()
for i=2^53,2^53+2 do io.write(i," ") end print()
for i=1,0/0 do print("nan loop") end print("nan limit: no iterations")
EOF
/workspace/executable /tmp/lua/for1.lua; echo exit=$?

cat > /tmp/lua/for2.lua <<'EOF'
for i=1,3 do io.write(i," ") end print()
for i=3,1 do io.write(i,"?") end print("empty")
for i=3,1,-1 do io.write(i," ") end print()
for i=1,10,3 do io.write(i," ") end print()
for i=1.0,3 do io.write(i," ",math.type(i),";") end print()
for i=1,3.5 do io.write(i," ",math.type(i),";") end print()
for i=0.5,3,0.5 do io.write(i," ") end print()
for i=math.maxinteger-2,math.maxinteger do io.write(i," ") end print()
for i=math.maxinteger-1,math.maxinteger do io.write(i," ") end print()
for i=math.mininteger,math.mininteger+1 do io.write(i," ") end print()
for i=math.maxinteger,math.mininteger,-1 do io.write(i,"!") end print("empty")
for i=1,3,-1 do io.write(i,"!") end print("empty2")
local ok,e = pcall(load("for i=1,10,0 do end")) print(ok,e)
ok,e = pcall(function() for i=1,10,0 do end end) print(ok,e)
for i=1,3 do local i = i * 10; io.write(i," ") end print()
for i=2^53,2^53+2 do io.write(i," ") end print()
