cat > /tmp/lua/for5.lua <<'EOF'
for i=1,3.0 do io.write(i,":",math.type(i),",") end print()
for i=1.0,3.0 do io.write(i,":",math.type(i),",") end print()
for i=1,3,1.0 do io.write(i,":",math.type(i),",") end print()
for i=1,3.7 do io.write(i,",") end print()
for i=1,3,2^63 do io.write(i,",") end print("(huge float step)")
for i=1,math.huge do if i>2 then print("inf limit ok") break end end
for i=-math.huge,-math.huge do io.write(i," ") end print()
print(load("for i='a','c' do end"))
print(pcall(function() for i='1','3' do io.write(i," ") end end))
EOF
/workspace/executable /tmp/lua/for5.lua; echo exit=$?

cat > /tmp/lua/tab1.lua <<'EOF'
-- constructors
local t1 = {1, 2, 3}
print(#t1, t1[1], t1[3])
local t2 = {1, 2, 3,}
print(#t2)
local t3 = {1; 2; 3;}
print(#t3, t3[2])
local t4 = {[1]="a", [3]="c", x=1, 10, 20}
print(t4[1], t4[3], t4.x, t4[2])
local t5 = {[2]="b", "a"}
print(t5[1], t5[2])
local t6 = {[0]=0, [-1]="neg", [1.5]="f", ["1"]="s1", [1]="int1"}
print(t6[0], t6[-1], t6[1.5], t6["1"], t6[1])
-- float keys normalized to integer keys
local t7 = {}
t7[2.0] = "float2"
print(t7[2], rawget(t7, 2.0))
t7[2.5] = "f25"
print(t7[2.5], rawget(t7, 2))
local big = 2^62
local t8 = {}
t8[big] = "big"
print(t8[big], t8[big + 0.0])
-- NaN key
print(pcall(function() t8[0/0] = 1 end))
print(pcall(function() t8[nil] = 1 end))
print(pcall(function() return t8[0/0] end))
-- constructor with function call last vs middle
local function three() return 1, 2, 3 end
local c1 = {three()}
print(#c1, c1[1], c1[3])
local c2 = {three(), three()}
print(#c2, c2[1], c2[2], c2[3], c2[4])
local c3 = {(three())}
print(#c3)
local c4 = {three(), 10}
print(#c4, c4[1], c4[2])
EOF
/workspace/executable /tmp/lua/tab1.lua; echo exit=$?
